import unittest
from solution import valid_parentheses

class T(unittest.TestCase):
    def test_mixed(self):
        self.assertTrue(valid_parentheses("{[()]}"))
    def test_wrong_order(self):
        self.assertFalse(valid_parentheses("([)]"))
    def test_empty(self):
        self.assertTrue(valid_parentheses(""))
    def test_extra_close(self):
        self.assertFalse(valid_parentheses("())"))
